#!/usr/bin/env python3
"""Ignored synthetic Windows output organization and explicit-action matrix."""
from __future__ import annotations
import argparse,datetime as dt,hashlib,importlib.util,json,os,platform,re,shutil,subprocess,sys,time
from pathlib import Path

BASELINE='83e41830a3b2a7f15ece4efa972f2d824ab716c6'
NAMES=['WinAudioClean.ps1','WinAudioClean.IO.ps1','WinAudioClean.Settings.ps1','WinAudioClean.Preview.ps1','WinAudioClean.Batch.ps1','WinAudioClean.Queue.ps1','WinAudioClean.Output.ps1']
MARKER='# Explicit local support export bypasses media/dependency initialization.'
MUSIC="[Environment]::GetFolderPath('MyMusic')"
CASES=['chosen-flat','music-flat','full-job','preview-job','batch-job','folder-job','batch-journal-override',
       'picker-open','open-failure','native-failure-open','music-empty','music-unc','music-blocked',
       'custom-empty-music','no-input','picker-cancel','redirected-pick','redirected-open','legacy-helper-missing','flat-junction',
       'queue-admission-cancel','organization-report-fault']
INSTRUMENTATION=r'''
# Development-only controlled OS-known-folder input and optional UI boundaries.
function Write-WacOutputHarnessEvent {
    param([System.Collections.IDictionary]$Record)
    if (-not $env:WAC_OUTPUT_HARNESS_EVENTS) { return }
    if (-not (Get-Variable WacOutputHarnessSequence -Scope Global -ErrorAction SilentlyContinue)) { $global:WacOutputHarnessSequence=0 }
    $global:WacOutputHarnessSequence++
    $Record.sequence=$global:WacOutputHarnessSequence
    $Record.atUtc=[DateTime]::UtcNow.ToString('o')
    $Record.hostPid=$PID
    $Record.inputPath=$script:inputPath
    [IO.File]::AppendAllText($env:WAC_OUTPUT_HARNESS_EVENTS,($Record|ConvertTo-Json -Depth 8 -Compress)+"`n",[Text.UTF8Encoding]::new($false))
}
$script:WacOutputHarnessNative=${function:Invoke-WacNativeProcess}
$script:WacOutputHarnessPublish=${function:Publish-WacOutputTransaction}
$script:WacOutputHarnessInteractive=${function:Test-WacInteractive}
$script:WacOutputHarnessOrganization=${function:Get-WacOutputOrganization}
$script:WacOutputHarnessPublished=$false
function Get-WacOutputOrganization {
    param($Layout)
    if ($env:WAC_OUTPUT_HARNESS_ORGANIZATION_FAULT -eq '1' -and $script:WacOutputHarnessPublished) {
        Write-WacOutputHarnessEvent -Record ([ordered]@{kind='organization_fault_after_publication'})
        throw 'Controlled output-organization report fault after audio publication.'
    }
    & $script:WacOutputHarnessOrganization @PSBoundParameters
}
function Test-WacInteractive {
    param([switch]$NonInteractive,[string[]]$HostArguments=[Environment]::GetCommandLineArgs(),
        [bool]$InputRedirected=[Console]::IsInputRedirected,[bool]$UserInteractive=[Environment]::UserInteractive)
    if ($env:WAC_OUTPUT_HARNESS_INTERACTIVE -eq '1') { return $true }
    & $script:WacOutputHarnessInteractive @PSBoundParameters
}
function Clear-Host {
    if ($env:WAC_OUTPUT_HARNESS_INTERACTIVE -ne '1') { throw 'Unexpected screen clear in redirected harness.' }
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='clear_host_noop'})
}
function Show-WacFilePicker {
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='picker';behavior=$env:WAC_OUTPUT_HARNESS_PICKER})
    if ($env:WAC_OUTPUT_HARNESS_PICKER -eq 'cancel') { return $null }
    if ($env:WAC_OUTPUT_HARNESS_PICKER -eq 'selected') { return $env:WAC_OUTPUT_HARNESS_SELECTED_INPUT }
    throw 'Unexpected picker call; no actual desktop dialog is allowed.'
}
function Open-WacDestinationFolder {
    param([Parameter(Mandatory=$true)][string]$Directory,[string]$ExpectedDirectoryIdentity)
    $resolved=Resolve-WacFileSystemPath -Path $Directory
    $exists=Test-Path -LiteralPath $resolved -PathType Container
    $identity=$null;$handle=$null
    try {
        if ($exists) { Initialize-WacNativeFileIO;$handle=[WinAudioClean.NativeFileIO]::OpenDirectory($resolved);$identity=[WinAudioClean.NativeFileIO]::Identity($handle) }
    } finally {if ($null -ne $handle) {$handle.Dispose()}}
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='open';directory=$resolved;exists=$exists;expectedDirectoryIdentity=$ExpectedDirectoryIdentity;actualDirectoryIdentity=$identity;behavior=$env:WAC_OUTPUT_HARNESS_OPEN})
    if (-not $exists) { throw 'Open spy received a nonexistent directory.' }
    if (-not $ExpectedDirectoryIdentity -or $identity -cne $ExpectedDirectoryIdentity) { throw 'Open spy directory identity mismatch.' }
    if ($env:WAC_OUTPUT_HARNESS_OPEN -eq 'fail') { throw 'Controlled optional folder-open failure.' }
    if ($env:WAC_OUTPUT_HARNESS_OPEN -ne 'record') { throw 'Unexpected folder-open call; no Explorer launch is allowed.' }
}
function Invoke-WacNativeProcess {
    param([string]$FilePath,[AllowEmptyCollection()][string[]]$ArgumentList=@(),[int]$TimeoutMilliseconds=0,
        [int]$StreamCloseTimeoutMilliseconds=5000,[System.IO.Stream]$StandardInputStream,$RunContext=$script:WacRunContext,$ProgressState)
    $original=@($ArgumentList);$forced=$false
    if ($env:WAC_OUTPUT_HARNESS_ADMISSION_CANCEL -eq '1' -and $ProgressState.Stage -eq 'Rendering' -and $RunContext.FileIndex -eq 1) {
        Request-WacCancellation -RunContext $RunContext
        Write-WacOutputHarnessEvent -Record ([ordered]@{kind='native_pre_admission_cancel';stage=$ProgressState.Stage;cancellationRequested=$RunContext.IsCancellationRequested;fileIndex=$RunContext.FileIndex;fileCount=$RunContext.FileCount})
    }
    if ($env:WAC_OUTPUT_HARNESS_RENDER_FAILURE -eq '1' -and $ProgressState.Stage -eq 'Rendering') {
        $index=[array]::IndexOf($ArgumentList,'-af')
        if ($index -lt 0) { throw 'Cannot locate filter for bounded native-failure injection.' }
        $ArgumentList=@($ArgumentList);$ArgumentList[$index+1]='wac_harness_missing_filter'
        $PSBoundParameters.ArgumentList=$ArgumentList;$forced=$true
    }
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='native_start';executable=$FilePath;arguments=@($ArgumentList);originalArguments=$original
        forcedRenderFailure=$forced;stage=$(if($ProgressState){$ProgressState.Stage}else{$null});inputStream=($null -ne $StandardInputStream)
        timeoutMilliseconds=$TimeoutMilliseconds;shellVersion=$PSVersionTable.PSVersion.ToString();culture=[Threading.Thread]::CurrentThread.CurrentCulture.Name})
    $result=& $script:WacOutputHarnessNative @PSBoundParameters
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='native_result';stage=$(if($ProgressState){$ProgressState.Stage}else{$null})
        started=$result.Started;exitCode=$result.ExitCode;cancelled=$result.Cancelled;ownedProcessId=$result.OwnedProcessId;timedOut=$result.TimedOut;error=$result.Error;cleanupError=$result.CleanupError})
    $result
}
function Publish-WacOutputTransaction {
    param($Transaction)
    & $script:WacOutputHarnessPublish @PSBoundParameters
    if ($Transaction.Published) { $script:WacOutputHarnessPublished=$true }
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='published';finalPath=$Transaction.FinalPath;published=$Transaction.Published;jobId=$Transaction.JobId})
}
'''

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--ffmpeg',type=Path,required=True);parser.add_argument('--ffprobe',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True)
    parser.add_argument('--shell',action='append',choices=['ps51','ps7']);parser.add_argument('--case',action='append',choices=CASES)
    args=parser.parse_args();repo=Path(__file__).resolve().parents[2];scratch=repo/'.wac-local/WAC-M3-05';output=args.output.resolve()
    if not output.is_relative_to(scratch):parser.error('Output must stay in ignored M3-05 scratch')
    output.mkdir(parents=True,exist_ok=False)
    for name in ['app','baseline','legacy','fixtures','cases','logs','references']:(output/name).mkdir()
    ffmpeg=args.ffmpeg.resolve(strict=True);ffprobe=args.ffprobe.resolve(strict=True)
    helper=repo/'scripts/Test-MeasuredLoudness.py'
    spec=importlib.util.spec_from_file_location('output_media_helpers',helper);helpers=importlib.util.module_from_spec(spec)
    previous=sys.dont_write_bytecode
    try:sys.dont_write_bytecode=True;spec.loader.exec_module(helpers)
    finally:sys.dont_write_bytecode=previous
    sha=helpers.sha256;immutable={};commands=[];references=[];results=[]
    source_paths=[repo/name for name in NAMES]+[helper,Path(__file__).resolve(),repo/'docs/codex/winaudioclean/BASELINE.json']
    source_data={path:path.read_bytes() for path in source_paths}
    sources_before={path.relative_to(repo).as_posix():hashlib.sha256(data).hexdigest() for path,data in source_data.items()}
    audio_baseline=json.loads(source_data[repo/'docs/codex/winaudioclean/BASELINE.json'].decode('utf-8-sig'))
    baseline_filters=audio_baseline['filters']['raw_clean']+','+audio_baseline['filters']['level']
    clean_env={key:value for key,value in os.environ.items() if key.upper()!='PSMODULEPATH' and not key.upper().startswith('WAC_OUTPUT_HARNESS_')}
    evidence={'task':'WAC-M3-05','started_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'source_revision':subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip(),
              'source_sha256_before':sources_before,'harness_invocation':sys.orig_argv,'scope':{'shell_filter':args.shell,'case_filter':args.case,'unfiltered':not args.shell and not args.case},
              'notice':'Synthetic real FFmpeg media only. Controlled Music known-folder input, eligibility/picker/open spies and no-op screen clear are labeled. No actual Music/settings/desktop UI/private audio/listening writes or claims.',
              'environment':{'python':platform.python_version(),'platform':platform.platform(),'child_psmodulepath_removed':True},'commands':commands,'references':references,'cases':results,'fixtures':[],
              'tools':{name:{'path':str(path),'sha256':sha(path)} for name,path in [('ffmpeg',ffmpeg),('ffprobe',ffprobe)]},'baseline_revision':BASELINE}
    def require(value,message):
        if not value:raise ValueError(message)
    def sanitize(value):
        if isinstance(value,Path):return sanitize(str(value))
        if isinstance(value,str):
            for old,new in [(str(repo),'<repo>'),(str(Path.home()),'<user-profile>')]:
                pattern=r'[\\/]+'.join(re.escape(part) for part in re.split(r'[\\/]+',old));value=re.sub(pattern,lambda match:new,value,flags=re.I)
            value=re.sub(r'(<S N="(?:User|Computer|PSComputerName)">)[^<]*(</S>)',r'\1&lt;local-identity&gt;\2',value)
            for key in ['USERNAME','COMPUTERNAME','USERDOMAIN']:
                if os.environ.get(key):value=re.sub(re.escape(os.environ[key]),'<local-identity>',value,flags=re.I)
            return value
        if isinstance(value,list):return [sanitize(item) for item in value]
        if isinstance(value,dict):return {key:sanitize(item) for key,item in value.items()}
        return value
    def remember(path):
        path=Path(path);digest=sha(path);immutable[path]=digest
        return {'path':path.relative_to(repo).as_posix(),'sha256':digest,'bytes':path.stat().st_size}
    def run(label,argv,env=None,cwd=None,binary=False):
        started=time.monotonic();child=subprocess.Popen([str(item) for item in argv],cwd=cwd or repo,env=env or clean_env,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        timed_out=False
        try:stdout,stderr=child.communicate(timeout=180)
        except subprocess.TimeoutExpired:
            timed_out=True;helpers.stop_owned_process_tree(child);stdout,stderr=child.communicate(timeout=10)
        record={'id':label,'command':[str(item) for item in argv],'cwd':str(cwd or repo),'pid':child.pid,'exit_code':child.returncode,'timed_out':timed_out,'elapsed_seconds':round(time.monotonic()-started,3)}
        for name,data in [('stdout',stdout),('stderr',stderr)]:
            is_binary=binary and name=='stdout';path=output/'logs'/(label+'-'+name+('.pcm' if is_binary else '.txt'))
            if is_binary:path.write_bytes(data)
            else:path.write_text(sanitize(data.decode('utf-8',errors='replace')),encoding='utf-8')
            record[name+'_native_bytes_sha256']=hashlib.sha256(data).hexdigest();record[name+'_log']=remember(path)
        commands.append(record)
        return dict(record,stdout=stdout if binary else stdout.decode('utf-8',errors='replace'),stderr=stderr.decode('utf-8',errors='replace'))
    def checked(label,argv,binary=False):
        result=run(label,argv,binary=binary);require(result['exit_code']==0 and not result['timed_out'],label+' failed');return result
    def quote(value):return "'"+str(value).replace("'","''")+"'"
    def instrument(data,current):
        text=data.decode('utf-8');require(text.count(MARKER)==1,'Missing unique early observation seam')
        music_count=text.count(MUSIC)
        if current:
            require(music_count==1,'Cannot isolate the known-folder read')
            text=text.replace(MUSIC,'$env:WAC_OUTPUT_HARNESS_MUSIC')
        text=text.replace(MARKER,INSTRUMENTATION.replace('\n','\r\n')+'\r\n'+MARKER)
        return text.encode('utf-8')
    def audio(label,path,bits,channels,frames):
        probe=json.loads(checked('probe-'+label,[ffprobe,'-v','error','-show_streams','-of','json',path])['stdout'])['streams']
        require(len(probe)==1,'Output stream count changed');stream=probe[0];expected_layout={1:'mono',2:'stereo'}[channels]
        pcm=checked('decode-'+label,[ffmpeg,'-nostdin','-hide_banner','-v','error','-i',path,'-map','0:a:0','-c:a',f'pcm_s{bits}le','-f',f's{bits}le','-'],True)['stdout']
        checks={'codec':stream['codec_name']==f'pcm_s{bits}le','bits':int(stream['bits_per_sample'])==bits,'rate':int(stream['sample_rate'])==48000,
                'channels':stream['channels']==channels,'layout':(stream.get('channel_layout') or expected_layout)==expected_layout,'frames':len(pcm)==frames*channels*(bits//8)}
        require(all(checks.values()),label+' format/frame mismatch')
        return dict(remember(path),frames=frames,bits=bits,channels=channels,decoded_pcm_sha256=hashlib.sha256(pcm).hexdigest(),checks=checks)
    def events(path):
        return [json.loads(line) for line in path.read_text(encoding='utf-8-sig').splitlines() if line] if path.exists() else []
    def inspect(folder,label,bits=16,channels=2,frames=192000):
        reports=[];assets=[]
        for path in sorted(folder.rglob('WinAudioClean_*.json')):
            record=remember(path);report=json.loads(path.read_text(encoding='utf-8-sig'))
            reports.append(dict(record,report=report))
            if report.get('reportType')=='preview':
                for role,item in report['assets'].items():assets.append(dict(audio(label+'-'+role,Path(item['path']),bits,channels,frames),role=role,report_job_id=report['jobId']))
            elif report.get('processingStatus')=='SUCCESS':
                assets.append(dict(audio(label+'-'+report['jobId'],Path(report['output']['path']),bits,channels,frames),report_job_id=report['jobId']))
        return reports,assets
    def app(label,shell,culture,options,env=None,application=None):
        case=output/'cases'/label;case.mkdir(exist_ok=True);cwd=case/'cwd';cwd.mkdir(exist_ok=True)
        sentinel=cwd/'sentinel.txt';sentinel.write_text('owned harness cwd sentinel\n',encoding='ascii');remember(sentinel)
        event_path=case/'events.jsonl';settings=case/'absent-settings.json'
        parameters=' -Mode Raw -Preset '+('Gentle' if options.get('accurate') else 'Original')+' -LoudnessMode '+('Accurate' if options.get('accurate') else 'Fast')+' -BitDepth '+('24' if options.get('accurate') else '16')+' -Mono:$'+str(bool(options.get('accurate'))).lower()
        if options.get('selection')=='batch':parameters+=' -InputPaths @('+quote(fixture)+','+quote(fixture)+')'
        elif options.get('selection')=='folder':parameters+=' -InputDirectories @('+quote(options['source_root'])+') -Recurse'
        elif not options.get('no_input') and not options.get('pick'):parameters+=' -inputPath '+quote(fixture)
        if options.get('pick'):parameters+=' -PickFile'
        if options.get('destination') is not None:parameters+=' -OutputDirectory '+quote(options['destination'])
        if options.get('job'):parameters+=' -JobFolder'
        if options.get('preview'):parameters+=' -Preview -PreviewStartSeconds 0.25 -PreviewDurationSeconds 1.5'
        if options.get('open'):parameters+=' -OpenOutputFolder'
        if options.get('journal'):parameters+=' -BatchResultPath '+quote(options['journal'])
        if not options.get('interactive'):parameters+=' -NonInteractive'
        parameters+=' -FfmpegPath '+quote(ffmpeg)+' -FfprobePath '+quote(ffprobe)+' -SettingsPath '+quote(settings)+' -IgnoreSavedSettings'
        facts=case/'host-facts.json'
        release_base=options.get('canonical_destination') or options.get('destination') or case/'controlled-music'
        release_probe=''
        if options.get('job'):
            release_probe='$releaseBase='+quote(release_base)+';$releaseRoots=@();if([IO.Directory]::Exists($releaseBase)){$releaseRoots=@([IO.Directory]::GetDirectories($releaseBase)|Where-Object{[IO.Path]::GetFileName($_) -cmatch "^WinAudioClean_Job_[0-9a-f]{32}$"})};if($releaseRoots.Count -eq 1){$originalRoot=[IO.Path]::GetFullPath($releaseRoots[0]);$probeRoot=$originalRoot+"_release_probe";if(-not $originalRoot.StartsWith([IO.Path]::GetFullPath($releaseBase)+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw "Release probe escaped owned case base"};try{[IO.Directory]::Move($originalRoot,$probeRoot);[IO.Directory]::Move($probeRoot,$originalRoot);$facts.groupHandlesReleased=$true}catch{$facts.groupHandlesReleased=$false;$facts.groupReleaseError=$_.Exception.Message}};'
        statement='$culture=[Globalization.CultureInfo]::GetCultureInfo('+quote(culture)+');[Threading.Thread]::CurrentThread.CurrentCulture=$culture;[Threading.Thread]::CurrentThread.CurrentUICulture=$culture;$formsBefore=@([AppDomain]::CurrentDomain.GetAssemblies()|Where-Object{$_.GetName().Name -eq "System.Windows.Forms"}).Count -gt 0;& '+quote(application or output/'app/WinAudioClean.ps1')+parameters+';$wacExit=$LASTEXITCODE;$facts=[ordered]@{formsLoadedBefore=$formsBefore;formsLoadedAfter=(@([AppDomain]::CurrentDomain.GetAssemblies()|Where-Object{$_.GetName().Name -eq "System.Windows.Forms"}).Count -gt 0);inputRedirected=[Console]::IsInputRedirected;shellVersion=$PSVersionTable.PSVersion.ToString();culture=[Threading.Thread]::CurrentThread.CurrentCulture.Name;groupHandlesReleased=$null};'+release_probe+'[IO.File]::WriteAllText('+quote(facts)+',($facts|ConvertTo-Json -Compress),[Text.UTF8Encoding]::new($false));exit $wacExit'
        environment=dict(clean_env,WAC_OUTPUT_HARNESS_EVENTS=str(event_path),WAC_OUTPUT_HARNESS_MUSIC=str(case/'controlled-music'),WAC_OUTPUT_HARNESS_INTERACTIVE='1' if options.get('interactive') else '0',
                         WAC_OUTPUT_HARNESS_PICKER='selected' if options.get('pick') else 'unexpected',WAC_OUTPUT_HARNESS_SELECTED_INPUT=str(fixture),WAC_OUTPUT_HARNESS_OPEN='record' if options.get('open') else 'unexpected')
        environment.update(env or {})
        result=run('app-'+label,[shell,'-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command',statement],env=environment,cwd=cwd)
        observed=events(event_path)
        if event_path.exists():remember(event_path)
        require(facts.is_file(),'App wrapper did not finish host-facts capture')
        remember(facts)
        return case,result,observed,cwd
    def graph_checks(reports,observed):
        checks=[]
        for record in reports:
            report=record['report']
            if report.get('processingStatus') not in (None,'SUCCESS'):continue
            filters={event['stage']:event['arguments'][event['arguments'].index('-af')+1] for event in observed if event['kind']=='native_start' and event['inputPath']==report['input']['path'] and '-af' in event['arguments']}
            if report.get('reportType')=='preview':
                checks.extend(filters.get(stage)==report['assets'][role]['exactFilters'] for stage,role in [('Preview Original rendering','Original'),('Preview Processed rendering','Processed'),('Preview Original comparison','CompareOriginal'),('Preview Processed comparison','CompareProcessed')])
            else:
                checks.append(filters.get('Rendering')==report['settings']['exactFilters'])
                if report['settings']['loudnessMode']=='Accurate':checks.extend([filters.get('Analysis')==report['normalization']['analysisFilter'],filters.get('Verification')==report['normalization']['finalMeasurementFilter']])
        return bool(checks) and all(checks)
    try:
        (output/'harness-tested.py').write_bytes(source_data[Path(__file__).resolve()]);evidence['tested_harness_copy']=remember(output/'harness-tested.py')
        baseline_copies={};copies={}
        for name in NAMES:
            path=repo/name;current_data=source_data[path];copy=output/'app'/name
            copy.write_bytes(instrument(current_data,True) if name=='WinAudioClean.ps1' else current_data);copies[copy.relative_to(repo).as_posix()]=sha(copy)
            if name!='WinAudioClean.Output.ps1':
                blob=subprocess.check_output(['git','show',BASELINE+':'+name],cwd=repo)
                baseline_data=blob.replace(b'\r\n',b'\n').replace(b'\n',b'\r\n')
                before=output/'baseline'/name;before.write_bytes(instrument(baseline_data,False) if name=='WinAudioClean.ps1' else baseline_data)
                baseline_copies[name]={'git_blob_sha256':hashlib.sha256(blob).hexdigest(),'normalized_physical_sha256':hashlib.sha256(baseline_data).hexdigest(),'instrumented_copy_sha256':sha(before)}
                copies[before.relative_to(repo).as_posix()]=sha(before)
                legacy=output/'legacy'/name;legacy.write_bytes(copy.read_bytes());copies[legacy.relative_to(repo).as_posix()]=sha(legacy)
        evidence['instrumentation']={'seam':MARKER,'known_folder_input':'Exactly one MyMusic OS read in the copied main is replaced with a controlled environment value. Actual default-origin/output validation remains real. The real user Music folder is never touched.',
                                     'native_failure':'Only requested Rendering -af is replaced with an unknown filter in a copied delegate; actual FFmpeg exits. Both original and actual argv captured.',
                                     'ui':'Picker/open boundary spies and controlled interactive eligibility; Clear-Host no-op only for the forced eligible child. No desktop dialog/Explorer is started.',
                                     'source':INSTRUMENTATION,'copies_before':copies,'baseline_copies':baseline_copies}
        for name,path in [('ffmpeg',ffmpeg),('ffprobe',ffprobe)]:evidence['tools'][name]['version']=checked(name+'-version',[path,'-version'])['stdout'].splitlines()[0]
        fixture=output/'fixtures/stereo.wav';evidence['fixtures'].append(dict(helpers.create_fixture(fixture,2,4,'eligible'),**remember(fixture)))
        shells={'ps51':str(Path(os.environ['SystemRoot'])/'System32/WindowsPowerShell/v1.0/powershell.exe'),'ps7':shutil.which('pwsh.exe')}
        for host in args.shell or ['ps51','ps7']:
            shell=shells[host];require(shell,host+' unavailable');culture={'ps51':'en-US','ps7':'de-DE'}[host];reference_data={};reference_exits={}
            for key in ['fast','accurate','preview']:
                label=host+'-reference-'+key;dest=output/'references'/label
                options={'destination':dest,'accurate':key=='accurate','preview':key=='preview'}
                folder,result,observed,cwd=app(label,shell,culture,options,application=output/'baseline/WinAudioClean.ps1')
                require(result['exit_code'] in (0,7) and not result['timed_out'],'Baseline '+key+' failed')
                reports,assets=inspect(dest,label,bits=24 if key=='accurate' else 16,channels=1 if key=='accurate' else 2,frames=72000 if key=='preview' else 192000)
                require(len(assets)==(4 if key=='preview' else 1) and graph_checks(reports,observed),'Baseline output/graph mismatch')
                reference_data[key]=assets;reference_exits[key]=result['exit_code'];references.append({'id':label,'application_exit':result['exit_code'],'reports':reports,'assets':assets,'events':observed})
            for name in args.case or CASES:
                label=host+'-'+name;folder=output/'cases'/label;folder.mkdir();dest=folder/'destination'
                options={'destination':dest};environment={};expected=(0,7);negative=False;evidence_case_journal=None;root=None
                if name in ['music-flat','music-empty','music-unc','music-blocked']:options['destination']=None
                if name=='full-job':options.update(job=True,accurate=True)
                if name=='preview-job':options.update(job=True,preview=True)
                if name in ['batch-job','batch-journal-override']:options.update(job=True,selection='batch')
                if name=='batch-job':options.update(open=True,interactive=True)
                if name=='batch-journal-override':options['journal']=folder/'explicit-result.jsonl'
                if name=='folder-job':
                    sources=folder/'sources';sources.mkdir();old=sources/('WinAudioClean_Job_'+'a'*32);old.mkdir();near=sources/'WinAudioClean_Job_near-miss';near.mkdir()
                    for path in [sources/'ordinary.wav',old/'renamedordinary.wav',near/'ordinary.wav']:shutil.copyfile(fixture,path);evidence['fixtures'].append(remember(path))
                    options.update(job=True,selection='folder',source_root=sources,destination=sources/'destination')
                if name=='flat-junction':
                    target=folder/'junction-target';target.mkdir();alias=folder/'junction-alias'
                    linked=run('create-'+label+'-junction',[Path(os.environ['SystemRoot'])/'System32/cmd.exe','/d','/c','mklink','/J',alias,target])
                    require(linked['exit_code']==0 and alias.is_dir(),'Controlled junction creation failed')
                    options.update(destination=alias,canonical_destination=target,open=True,interactive=True)
