# Development-only controlled OS-known-folder input and optional UI boundaries.
function Write-WacOutputHarnessEvent {
    param([System.Collections.IDictionary]$Record)
    if (-not $env:WAC_OUTPUT_HARNESS_EVENTS) { return }
    if (-not (Get-Variable WacOutputHarnessSequence -Scope Global -ErrorAction SilentlyContinue)) { $global:WacOutputHarnessSequence=0 }
    $global:WacOutputHarnessSequence++
    $Record.sequence=$global:WacOutputHarnessSequence
    $Record.atUtc=[DateTime]::UtcNow.ToString('o')
    $Record.hostPid=$PID
    $Record.inputPath=$script:inputPath
    [IO.File]::AppendAllText($env:WAC_OUTPUT_HARNESS_EVENTS,($Record|ConvertTo-Json -Depth 8 -Compress)+"`n",[Text.UTF8Encoding]::new($false))
}
$script:WacOutputHarnessNative=${function:Invoke-WacNativeProcess}
$script:WacOutputHarnessPublish=${function:Publish-WacOutputTransaction}
$script:WacOutputHarnessInteractive=${function:Test-WacInteractive}
$script:WacOutputHarnessOrganization=${function:Get-WacOutputOrganization}
$script:WacOutputHarnessPublished=$false
function Get-WacOutputOrganization {
    param($Layout)
    if ($env:WAC_OUTPUT_HARNESS_ORGANIZATION_FAULT -eq '1' -and $script:WacOutputHarnessPublished) {
        Write-WacOutputHarnessEvent -Record ([ordered]@{kind='organization_fault_after_publication'})
        throw 'Controlled output-organization report fault after audio publication.'
    }
    & $script:WacOutputHarnessOrganization @PSBoundParameters
}
function Test-WacInteractive {
    param([switch]$NonInteractive,[string[]]$HostArguments=[Environment]::GetCommandLineArgs(),
        [bool]$InputRedirected=[Console]::IsInputRedirected,[bool]$UserInteractive=[Environment]::UserInteractive)
    if ($env:WAC_OUTPUT_HARNESS_INTERACTIVE -eq '1') { return $true }
    & $script:WacOutputHarnessInteractive @PSBoundParameters
}
function Clear-Host {
    if ($env:WAC_OUTPUT_HARNESS_INTERACTIVE -ne '1') { throw 'Unexpected screen clear in redirected harness.' }
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='clear_host_noop'})
}
function Show-WacFilePicker {
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='picker';behavior=$env:WAC_OUTPUT_HARNESS_PICKER})
    if ($env:WAC_OUTPUT_HARNESS_PICKER -eq 'cancel') { return $null }
    if ($env:WAC_OUTPUT_HARNESS_PICKER -eq 'selected') { return $env:WAC_OUTPUT_HARNESS_SELECTED_INPUT }
    throw 'Unexpected picker call; no actual desktop dialog is allowed.'
}
function Open-WacDestinationFolder {
    param([Parameter(Mandatory=$true)][string]$Directory,[string]$ExpectedDirectoryIdentity)
    $resolved=Resolve-WacFileSystemPath -Path $Directory
    $exists=Test-Path -LiteralPath $resolved -PathType Container
    $identity=$null;$handle=$null
    try {
        if ($exists) { Initialize-WacNativeFileIO;$handle=[WinAudioClean.NativeFileIO]::OpenDirectory($resolved);$identity=[WinAudioClean.NativeFileIO]::Identity($handle) }
    } finally {if ($null -ne $handle) {$handle.Dispose()}}
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='open';directory=$resolved;exists=$exists;expectedDirectoryIdentity=$ExpectedDirectoryIdentity;actualDirectoryIdentity=$identity;behavior=$env:WAC_OUTPUT_HARNESS_OPEN})
    if (-not $exists) { throw 'Open spy received a nonexistent directory.' }
    if (-not $ExpectedDirectoryIdentity -or $identity -cne $ExpectedDirectoryIdentity) { throw 'Open spy directory identity mismatch.' }
    if ($env:WAC_OUTPUT_HARNESS_OPEN -eq 'fail') { throw 'Controlled optional folder-open failure.' }
    if ($env:WAC_OUTPUT_HARNESS_OPEN -ne 'record') { throw 'Unexpected folder-open call; no Explorer launch is allowed.' }
}
function Invoke-WacNativeProcess {
    param([string]$FilePath,[AllowEmptyCollection()][string[]]$ArgumentList=@(),[int]$TimeoutMilliseconds=0,
        [int]$StreamCloseTimeoutMilliseconds=5000,[System.IO.Stream]$StandardInputStream,$RunContext=$script:WacRunContext,$ProgressState)
    $original=@($ArgumentList);$forced=$false
    if ($env:WAC_OUTPUT_HARNESS_ADMISSION_CANCEL -eq '1' -and $ProgressState.Stage -eq 'Rendering' -and $RunContext.FileIndex -eq 1) {
        Request-WacCancellation -RunContext $RunContext
        Write-WacOutputHarnessEvent -Record ([ordered]@{kind='native_pre_admission_cancel';stage=$ProgressState.Stage;cancellationRequested=$RunContext.IsCancellationRequested;fileIndex=$RunContext.FileIndex;fileCount=$RunContext.FileCount})
    }
    if ($env:WAC_OUTPUT_HARNESS_RENDER_FAILURE -eq '1' -and $ProgressState.Stage -eq 'Rendering') {
        $index=[array]::IndexOf($ArgumentList,'-af')
        if ($index -lt 0) { throw 'Cannot locate filter for bounded native-failure injection.' }
        $ArgumentList=@($ArgumentList);$ArgumentList[$index+1]='wac_harness_missing_filter'
        $PSBoundParameters.ArgumentList=$ArgumentList;$forced=$true
    }
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='native_start';executable=$FilePath;arguments=@($ArgumentList);originalArguments=$original
        forcedRenderFailure=$forced;stage=$(if($ProgressState){$ProgressState.Stage}else{$null});inputStream=($null -ne $StandardInputStream)
        timeoutMilliseconds=$TimeoutMilliseconds;shellVersion=$PSVersionTable.PSVersion.ToString();culture=[Threading.Thread]::CurrentThread.CurrentCulture.Name})
    $result=& $script:WacOutputHarnessNative @PSBoundParameters
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='native_result';stage=$(if($ProgressState){$ProgressState.Stage}else{$null})
        started=$result.Started;exitCode=$result.ExitCode;cancelled=$result.Cancelled;ownedProcessId=$result.OwnedProcessId;timedOut=$result.TimedOut;error=$result.Error;cleanupError=$result.CleanupError})
    $result
}
function Publish-WacOutputTransaction {
    param($Transaction)
    & $script:WacOutputHarnessPublish @PSBoundParameters
    if ($Transaction.Published) { $script:WacOutputHarnessPublished=$true }
    Write-WacOutputHarnessEvent -Record ([ordered]@{kind='published';finalPath=$Transaction.FinalPath;published=$Transaction.Published;jobId=$Transaction.JobId})
}

