"""Publish compact synthetic output-layout/action evidence; no media or raw reports."""
from pathlib import Path
import argparse,datetime as dt,hashlib,json,os,re

parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--capture',type=Path,required=True)
parser.add_argument('--expected-main-sha256',required=True)
args=parser.parse_args()
repo=Path(__file__).resolve().parents[2]
scratch=repo/'.wac-local/WAC-M3-05'
destination=repo/'docs/codex/winaudioclean/evidence'
names=['WinAudioClean.ps1','WinAudioClean.IO.ps1','WinAudioClean.Settings.ps1','WinAudioClean.Preview.ps1','WinAudioClean.Batch.ps1','WinAudioClean.Queue.ps1','WinAudioClean.Output.ps1']
guards=['sources_unchanged','files_unchanged','copies_unchanged','tools_unchanged']

def sha(data):return hashlib.sha256(data).hexdigest()
def require(value,message):
    if not value:raise ValueError(message)
def record(path):
    path=Path(path).resolve(strict=True);require(path.is_relative_to(repo),'Local record escaped repository')
    data=path.read_bytes();return {'path':path.relative_to(repo).as_posix(),'sha256':sha(data),'bytes':len(data)}
def sanitize(value):
    if isinstance(value,str):
        for original,replacement in [(str(repo),'<repo>'),(str(Path.home()),'<user-profile>')]:
            pattern=r'[\\/]+'.join(re.escape(part) for part in re.split(r'[\\/]+',original))
            value=re.sub(pattern,lambda match:replacement,value,flags=re.I)
        value=re.sub(r'(<S N="(?:User|Computer|PSComputerName)">)[^<]*(</S>)',r'\1&lt;local-identity&gt;\2',value)
        for key in ['USERNAME','COMPUTERNAME','USERDOMAIN']:
            if os.environ.get(key):value=re.sub(re.escape(os.environ[key]),'<local-identity>',value,flags=re.I)
        return value
    if isinstance(value,list):return [sanitize(item) for item in value]
    if isinstance(value,dict):return {key:sanitize(item) for key,item in value.items()}
    return value
def publish(name,data):
    path=destination/name;require(not path.exists(),'Refusing to replace '+name)
    encoded=(json.dumps(sanitize(data),indent=2,ensure_ascii=False,allow_nan=False)+'\n').encode('utf-8')
    # The final encoded bytes are checked too, including paths escaped through several JSON levels.
    for literal in [str(repo),str(Path.home()),os.environ.get('USERNAME',''),os.environ.get('COMPUTERNAME',''),os.environ.get('USERDOMAIN','')]:
        if literal:require(literal.lower() not in encoded.decode('utf-8').lower(),'Unsanitized identity in '+name)
    path.write_bytes(encoded);result=record(path);print(json.dumps(result));return result
def report_projection(item):
    report=item['report'];result={key:item[key] for key in ['path','sha256','bytes']}
    fields={key:report[key] for key in ['schemaVersion','jobId','status','applicationExitCode','presetId','presetVersion','presetCustomized','presetExperimental','settings','warningCodes'] if key in report}
    for key in ['processingStatus','processingExitCode','nativeExitCode','reasonCodes','diagnostics']:
        if key in report:fields[key]=report[key]
    if 'progress' in report:
        progress=report['progress'];fields['progress']={key:progress.get(key) for key in ['cancellationRequested','cancellationStage']}
        fields['progress']['stages']=[{key:stage.get(key) for key in ['stage','fileIndex','fileCount','percent','structuredEnd']} for stage in progress.get('stages',[])]
    if report.get('reportType')=='preview':
        fields.update(reportType='preview',range=report['range'],outputOrganization=report.get('outputOrganization'),matching=report.get('matching'))
        fields['assets']={role:{key:asset[key] for key in ['path','exactFilters','gainDb','frames','format'] if key in asset} for role,asset in report['assets'].items()}
    else:
        fields['output']={key:report['output'][key] for key in ['path','published','validity','format','organization'] if key in report['output']}
        fields['normalization']={key:report.get('normalization',{}).get(key) for key in ['requestedMode','analysisFilter','renderFilter','finalMeasurementFilter','actualType','fallbackReason']}
    result['fields']=fields;return result
def events_projection(events):
    # Preserve each exact media argv once. Inspection commands use digests; every complete event log is pinned.
    starts=[event for event in events if event['kind']=='native_start'];ends=[event for event in events if event['kind']=='native_result']
    require(len(starts)==len(ends),'Native capture start/result mismatch')
    media=[];inspection=[]
    for start,end in zip(starts,ends):
        require(start['stage']==end['stage'] and start['sequence']<end['sequence'],'Native capture ordering mismatch')
        item={'startSequence':start['sequence'],'resultSequence':end['sequence'],'stage':start['stage'],
              'arguments_unmodified':start['arguments']==start['originalArguments'],
              'captured_arguments_sha256_sanitized':sha(json.dumps(start['arguments'],ensure_ascii=False).encode('utf-8')),
              'outcome':{key:end[key] for key in ['started','exitCode','cancelled','ownedProcessId','timedOut','error','cleanupError']}}
        if start['stage']:
            item.update(executable=start['executable'],arguments=start['arguments'],inputStream=start['inputStream'],forcedRenderFailure=start['forcedRenderFailure'])
            if not item['arguments_unmodified']:item['original_arguments_sha256_sanitized']=sha(json.dumps(start['originalArguments'],ensure_ascii=False).encode('utf-8'))
            media.append(item)
        else:inspection.append(item)
    return {'scope':'Every exact media native argv/outcome and requested action/publication, with inspection command digests/outcomes. Full original event bytes remain ignored and hashed.',
            'media_native_calls':media,'inspection_native_calls':inspection,
            'actions':[event for event in events if event['kind'] not in ['native_start','native_result']]}

def command_digest(command):
    return {'id':command['id'],'exit_code':command['exit_code'],'timed_out':command['timed_out'],
            'captured_command_sha256_sanitized':sha(json.dumps(command['command'],ensure_ascii=False).encode('utf-8'))}

capture_path=args.capture.resolve(strict=True)
